NAV_GROUPS.map((group) => ({
        ...group,
        items: group.items.filter((item) =>
          item.ownerOnly ? ownsAnyFarm && can(item.perm) : can(item.perm),
        ),
      })).filter((group) => group.items.length > 0)

eligibleDoeCount === 0 ? (
          <p className="text-muted-foreground">
