                  (method === "NATURAL" && !hasEligibleBuck)
                }
              >
                {/* react-hook-form's isSubmitting spans the entire submit
                    window (the flight starts inside the handler). */}
                {isSubmitting
                  ? "Saving…"
                  : formError
                    ? "Retry save breeding"
                    : "Save breeding"}
              </Button>
            </DialogFooter>
            </fieldset>
          </form>
        )

